ee:message.ee:set-payload:
%dw 2.0 output application/json
var repeatX = (n) -> (1 to n) map "X" joinBy ""
var maskPan = (pan) -> if (pan == null or isBlank(pan)) null else if (sizeOf(pan) <= 4) pan else repeatX(sizeOf(pan) - 4) ++ pan[-4 to -1]
var maskAadhaar = (aadhaar) -> if (aadhaar == null or isBlank(aadhaar)) null else if (sizeOf(aadhaar) <= 4) aadhaar else "XXXX XXXX " ++ aadhaar[-4 to -1]
var formatTs = (ts) -> if (ts == null) null else ts as String {format: "yyyy-MM-dd'T'HH:mm:ss"}
var activeAccounts = sizeOf(vars.accounts filter ($.account_status == "ACTIVE")) var totalBalance = sum(vars.accounts map (($.balance as Number) default 0)) --- { status: "SUCCESS", customer: { customerId: vars.customer.customer_id, firstName: vars.customer.first_name, lastName: vars.customer.last_name, email: vars.customer.email, phone: vars.customer.phone, pan: maskPan(vars.customer.pan), aadhaar: maskAadhaar(vars.customer.aadhaar), city: vars.customer.city, state: vars.customer.state }, accountSummary: { totalAccounts: sizeOf(vars.accounts), activeAccounts: activeAccounts, totalBalance: totalBalance }, accounts: vars.accounts map (acc) -> { accountNumber: acc.account_number, accountType: acc.account_type, balance: acc.balance, status: acc.account_status, createdAt: formatTs(acc.created_at) }, kyc: if (vars.kyc == null) { verificationStatus: "NOT_AVAILABLE", panVerified: false, aadhaarVerified: false } else { verificationStatus: vars.kyc.verification_status, panVerified: vars.kyc.pan_verified, aadhaarVerified: vars.kyc.aadhaar_verified, remarks: vars.kyc.remarks, verifiedAt: formatTs(vars.kyc.verified_at) } }
